+/** Character edits between two env names, used to spot a misspelt shop setting. */
+function editDistance(a: string, b: string): number {
+  // One row of the Levenshtein table: row[j] is the distance for a.slice(0, i) and b.slice(0, j).
+  const row = Array.from({ length: b.length + 1 }, (_, j) => j);
+  for (let i = 1; i <= a.length; i++) {
+    // The value from the previous row at j - 1, saved before this row overwrites it.
+    let diagonal = i - 1;
+    row[0] = i;
+    for (let j = 1; j <= b.length; j++) {
+      const above = row[j] ?? 0;
+      const substitute = diagonal + (a[i - 1] === b[j - 1] ? 0 : 1);
+      row[j] = Math.min(above + 1, (row[j - 1] ?? 0) + 1, substitute);
+      diagonal = above;
+    }
+  }
+  return row[b.length] ?? 0;
+}
+
+/** Close enough to a shop setting's name that it is more likely a typo than a stranger. */
+function isMisspelt(key: string, known: string): boolean {
+  return Math.abs(key.length - known.length) <= 2 && editDistance(key, known) <= 2;
+}
+
+/**
+ * The env entries the shop settings are read from. process.env carries plenty of keys the
+ * shop doesn't own (PATH, NODE_ENV, ...), which must not fail the parse; a near-miss
+ * spelling of one of our keys is kept so the strict schema still rejects it loudly.
+ */
+function shopEnv(env: Env): Env {
+  const picked: Env = {};
+  for (const [key, value] of Object.entries(env)) {
+    const ours =
+      isShopSettingKey(key) ||
+      SHOP_SETTING_KEYS.some((known) => isMisspelt(key.toUpperCase(), known));
+    if (ours) picked[key] = value;
+  }
+  return picked;
+}
